/*
 * Solder Autonomous Firmware
 * Project: Usb Mechanical Macro Keypad
 * Target: Arduino Uno R3
 * Description: Generated responsive embedded control firmware.
 */

#include <Wire.h>

void setup() {
  Serial.begin(9600);
  pinMode(9, OUTPUT);
  digitalWrite(9, LOW);
  Serial.println(F("SYSTEM_BOOT: OK"));
  Serial.println(F("SOLDER_PROJECT_READY"));
}

void loop() {
  digitalWrite(9, HIGH);
  Serial.println(F("LAMP:ACTIVE"));
  Serial.println(F("OLED:FRAME_REFRESHED"));
  Serial.println(F("CYCLE_HEARTBEAT: OK"));
  delay(1000);
}
